window.HOEREN_TESTS[67] = {"id":"in-der-kantine","name":"In der Kantine","teile":[{"type":"mc","title":"Teil 1: Fünf kurze Texte","instruction":"Sie hören fünf kurze Texte. Sie hören jeden Text zweimal. Wählen Sie a, b oder c.","items":[{"transcript":"Liebe Mitarbeiter: Unsere Kantine hat ab Montag ein neues System. Sie zahlen nicht mehr mit Bargeld und nicht mit dem Handy, sondern nur noch mit der Mitarbeiterkarte. Geld können Sie am Automaten am Eingang aufladen. Das Essen wird dadurch günstiger. Die alte Kasse schließt am Freitag. Vielen Dank!","gender":"f","q":"Wie zahlt man ab Montag in der Kantine?","opts":["Mit der Mitarbeiterkarte.","Mit Bargeld.","Mit dem Handy."],"correct":0},{"transcript":"Hallo Tom, hier ist Markus. Gehst du heute in die Kantine? Es gibt dein Lieblingsessen — Schnitzel mit Pommes, nicht Pizza und nicht nur Suppe. Aber komm früh, sonst ist es schnell weg. Ich gehe schon um 12 Uhr. Treffen wir uns am Eingang? Ich halte dir einen Platz frei. Bis gleich!","gender":"m","q":"Was gibt es heute in der Kantine?","opts":["Schnitzel mit Pommes.","Pizza.","Suppe."],"correct":0},{"transcript":"Achtung Gäste: Wegen einer Renovierung in der Küche bietet die Kantine diese Woche nur kalte Gerichte an. Es gibt Salate, Brötchen und Obst, aber kein warmes Essen. Ab nächster Woche ist wieder alles normal. Wer warmes Essen möchte, kann das Restaurant nebenan nutzen. Danke für Ihr Verständnis!","gender":"m","q":"Was gibt es diese Woche nicht?","opts":["Salate.","Warmes Essen.","Brötchen."],"correct":1},{"transcript":"Hi Lisa, hier ist Anna. Ich esse jetzt jeden Tag in der Kantine, nicht mehr im Restaurant. Es ist viel günstiger, nicht weil es näher ist und nicht weil es besser schmeckt als zu Hause. Das Essen ist trotzdem gut. Heute gab es ein leckeres vegetarisches Gericht. Du solltest auch mal kommen! Sag Bescheid!","gender":"f","q":"Warum isst Anna jetzt in der Kantine?","opts":["Es schmeckt besser als zu Hause.","Es ist näher.","Es ist günstiger."],"correct":2},{"transcript":"Liebe Mitarbeiter: Ab Mai gibt es in der Kantine täglich ein vegetarisches und ein veganes Gericht, nicht nur Fleischgerichte und nicht nur Salat. Auch eine Suppe und ein Salatbuffet stehen jeden Tag bereit. Wer eine Allergie hat, fragt bitte das Personal. Die Speisekarte für die Woche hängt am Eingang aus. Guten Appetit!","gender":"f","q":"Was gibt es ab Mai jeden Tag?","opts":["Nur Fleischgerichte.","Nur Salat.","Ein vegetarisches und ein veganes Gericht."],"correct":2}]},{"type":"match","title":"Teil 2: Ein Gespräch","instruction":"Sie hören ein Gespräch. Sie hören den Text einmal. Was gibt es an welchem Tag? Wählen Sie für jeden Tag einen Buchstaben (a–i).","lines":[{"speaker":"Lukas","gender":"m","text":"Hallo Lisa! Die Kantine hat den Speiseplan für diese Woche aufgehängt."},{"speaker":"Lisa","gender":"f","text":"Schön, dass du ihn vorliest. Ich will den Plan schon am Morgen kennen."},{"speaker":"Lukas","gender":"m","text":"Es gibt am Montag Schnitzel. Der Kartoffelbrei liegt daneben auf dem Teller."},{"speaker":"Lisa","gender":"f","text":"Dienstag steht ein großer Salat in der Schüssel. Viel frisches Grün liegt obenauf."},{"speaker":"Lukas","gender":"m","text":"Steht Pizza auch irgendwo auf dem Plan?"},{"speaker":"Lisa","gender":"f","text":"Nein. Pizza gibt es in dieser Woche nicht."},{"speaker":"Lukas","gender":"m","text":"Die Mitte der Woche bleibt ohne Fleisch."},{"speaker":"Lisa","gender":"f","text":"Vegetarische Nudeln gibt es am Mittwoch. Die rote Soße hat nur Tomaten."},{"speaker":"Lukas","gender":"m","text":"Etwas Warmes soll im tiefen Becher kommen."},{"speaker":"Lisa","gender":"f","text":"Es gibt am Donnerstag Suppe. Sie ist dick und duftet stark nach Kräutern."},{"speaker":"Lukas","gender":"m","text":"Gibt es Currywurst als kleines Extra dazu?"},{"speaker":"Lisa","gender":"f","text":"Nein. Currywurst bieten wir nicht an. Die steht nur im Stadion."},{"speaker":"Lukas","gender":"m","text":"Gegen Ende der Woche riecht es in der Kantine nach der Küste."},{"speaker":"Lisa","gender":"f","text":"Der Koch brät am Freitag Fisch mit einer frischen Zitrone."},{"speaker":"Lukas","gender":"m","text":"Dann hänge ich eine Kopie neben unseren Kühlschrank."},{"speaker":"Lisa","gender":"f","text":"Ich richte mich morgens danach und nehme den passenden Teller."}],"options":[{"letter":"a","text":"Suppe"},{"letter":"b","text":"Reis mit Gemüse"},{"letter":"c","text":"Schnitzel"},{"letter":"d","text":"Pizza"},{"letter":"e","text":"Großer Salat"},{"letter":"f","text":"Fisch"},{"letter":"g","text":"Nur Nachtisch"},{"letter":"h","text":"Nudeln (vegetarisch)"},{"letter":"i","text":"Currywurst"}],"items":[{"person":"Montag","correct":"c"},{"person":"Dienstag","correct":"e"},{"person":"Mittwoch","correct":"h"},{"person":"Donnerstag","correct":"a"},{"person":"Freitag","correct":"f"}]},{"type":"mc","title":"Teil 3: Fünf kurze Gespräche","instruction":"Sie hören fünf kurze Gespräche. Sie hören jedes Gespräch einmal. Wählen Sie a, b oder c.","items":[{"lines":[{"speaker":"Mitarbeiter","gender":"m","text":"Guten Tag, was kostet das Menü heute bitte? 5 Euro vielleicht, oder weniger?"},{"speaker":"Köchin","gender":"f","text":"Mit Mitarbeiterkarte 4 Euro 50, nicht 5 Euro."},{"speaker":"Mitarbeiter","gender":"m","text":"Und für Gäste?"},{"speaker":"Köchin","gender":"f","text":"Für Gäste 7 Euro. Also 4 Euro 50 mit Karte, 7 Euro ohne."},{"speaker":"Mitarbeiter","gender":"m","text":"Ich habe einen Gast dabei, dann zahle ich 7 Euro für ihn und 4 Euro 50 für mich. Danke."}],"q":"Was kostet das Menü für Gäste?","opts":["4 Euro 50.","5 Euro.","7 Euro."],"correct":2},{"lines":[{"speaker":"Kollegin","gender":"f","text":"Guten Tag, ich möchte wissen, ob im Auflauf Fleisch und Nüsse drin sind. Nicht wie viel er kostet und nicht wann er fertig ist."},{"speaker":"Koch","gender":"m","text":"Der Auflauf ist vegetarisch, also ohne Fleisch."},{"speaker":"Kollegin","gender":"f","text":"Und Nüsse? Ich habe eine Allergie."},{"speaker":"Koch","gender":"m","text":"Nein, keine Nüsse drin. Fleisch und Nüsse sind beide nicht im Auflauf."},{"speaker":"Kollegin","gender":"f","text":"Perfekt, dann nehme ich den Auflauf. Danke!"}],"q":"Was möchte die Kollegin wissen?","opts":["Wann es fertig ist.","Wie viel es kostet.","Ob Fleisch und Nüsse drin sind."],"correct":2},{"lines":[{"speaker":"Mann","gender":"m","text":"Entschuldigung, wo bekomme ich einen Nachtisch? Am Eingang oder an der Kasse, wissen Sie das?"},{"speaker":"Frau","gender":"f","text":"Nicht am Eingang und nicht an der Kasse. Am Ende der Theke."},{"speaker":"Mann","gender":"m","text":"Was gibt es dort?"},{"speaker":"Frau","gender":"f","text":"Pudding und Obstsalat. Gehen Sie einfach ans Ende der Theke."},{"speaker":"Mann","gender":"m","text":"Danke, dann hole ich den Nachtisch am Ende der Theke, den Pudding."}],"q":"Wo gibt es den Nachtisch?","opts":["Am Ende der Theke.","Am Eingang.","An der Kasse."],"correct":0},{"lines":[{"speaker":"Kollege","gender":"m","text":"Ist hier noch frei? Die Kantine ist ja voll. Gibt es ein Fest oder günstige Preise?"},{"speaker":"Kollegin","gender":"f","text":"Ja, setz dich. Ein Fest ist nicht, und die Preise sind wie immer."},{"speaker":"Kollege","gender":"m","text":"Warum ist es dann so voll heute?"},{"speaker":"Kollegin","gender":"f","text":"Weil das Wetter schlecht ist. Draußen will niemand essen."},{"speaker":"Kollege","gender":"m","text":"Stimmt, wegen des schlechten Wetters. Danke für den Platz."}],"q":"Warum ist die Kantine heute voll?","opts":["Wegen eines Festes.","Wegen des schlechten Wetters.","Wegen günstiger Preise."],"correct":1},{"lines":[{"speaker":"Gast","gender":"m","text":"Entschuldigung, meine Karte funktioniert nicht. Kann ich an der Kasse oder im Büro aufladen?"},{"speaker":"Kassiererin","gender":"f","text":"An der Kasse und im Büro nicht. Vielleicht ist die Karte leer."},{"speaker":"Gast","gender":"m","text":"Wo lade ich sie dann auf?"},{"speaker":"Kassiererin","gender":"f","text":"Am Automaten beim Eingang. Dort geht es schnell."},{"speaker":"Gast","gender":"m","text":"Gut, ich gehe zum Automaten beim Eingang. Danke."}],"q":"Wo kann der Gast die Karte aufladen?","opts":["An der Kasse.","Am Automaten beim Eingang.","Im Büro."],"correct":1}]},{"type":"jn","title":"Teil 4: Interview","instruction":"Sie hören ein Interview mit Frau Becker, einer Kantinenleiterin. Sie hören das Interview zweimal. Ja oder Nein?","transcript":[{"speaker":"Reporter","gender":"m","text":"Frau Becker, wie viele Essen kochen Sie hier in der Kantine am Tag?"},{"speaker":"Becker","gender":"f","text":"Etwa achthundert. Wir fangen früh am Morgen an, damit alles um zwölf fertig ist. Das ist viel Arbeit, aber wir sind ein gutes Team in der Küche."},{"speaker":"Reporter","gender":"m","text":"Hat sich das Essen in den letzten Jahren verändert?"},{"speaker":"Becker","gender":"f","text":"Ja, früher wollten alle Fleisch. Heute essen viele lieber vegetarisch. Deshalb haben wir immer ein Gericht ohne Fleisch auf der Karte, das kommt gut an."},{"speaker":"Reporter","gender":"m","text":"Was ist für Sie am schwersten an der Arbeit?"},{"speaker":"Becker","gender":"f","text":"Es allen recht zu machen. Jeder mag etwas anderes. Der eine will scharf, der andere will milde. Da muss man Kompromisse finden."},{"speaker":"Reporter","gender":"m","text":"Was machen Sie mit den Resten am Abend?"},{"speaker":"Becker","gender":"f","text":"Wir werfen sie nicht weg. Wir geben das Essen an arme Menschen, an eine Tafel in der Stadt. Das ist uns wichtig, Essen wegwerfen wollen wir nicht."},{"speaker":"Reporter","gender":"m","text":"Was wünschen Sie sich von den Gästen?"},{"speaker":"Becker","gender":"f","text":"Dass sie uns sagen, was gut war und was nicht. Kritik hilft uns. Auch ein Dankeschön macht uns froh, wenn der Tag lang war."}],"items":[{"q":"Die Kantine kocht etwa achthundert Essen am Tag.","correct":"ja"},{"q":"Heute wollen alle Gäste jeden Tag Fleisch.","correct":"nein"},{"q":"Frau Becker findet es schwer, es allen recht zu machen.","correct":"ja"},{"q":"Die Reste werden weggeworfen.","correct":"nein"},{"q":"Sie möchte von den Gästen wissen, was gut war.","correct":"ja"}]}]};
